  (947, 149, 4, 'product', 753, '510646', 'BRUSH COUNTER BLACK HAIR  Black bristle or nylon hair for sweeping dust or dirt on desks, counters, or tables.', 753, 653, 12.0, 21, 30000.00, 18000.0, 5.0, FALSE, 1, 1),
  (948, 149, 5, 'product', 754, '510615', 'BRUSH DECK NYLON 450MM WIDTH, WITH LONG HANDLE  Deck brush with stiff nylon bristles for scrubbing the deck or sweeping floors.  Standard block size is 180 x 60 x 50 (Hair), 300 x 65 x 50 and 450 x 65 x 50 mm.', 754, 654, 24.0, 21, 100000.00, 60000.0, 5.0, FALSE, 1, 1),
